import AVFoundation

/// Calm looping track (generated by `scripts/generate_music.py`) that plays while a puzzle is in progress.
@MainActor
final class BackgroundMusic {
    static let shared = BackgroundMusic()

    private static let volume: Float = 0.5
    private var player: AVAudioPlayer?
    private var fadeTask: Task<Void, Never>?

    func play() {
        fadeTask?.cancel()
        if player == nil, let url = Bundle.module.url(forResource: "calm-loop", withExtension: "m4a") {
            // Ambient: respects the silent switch and mixes with the player's own music.
            try? AVAudioSession.sharedInstance().setCategory(.ambient)
            player = try? AVAudioPlayer(contentsOf: url)
            player?.numberOfLoops = -1
        }
        guard let player else { return }
        if !player.isPlaying { player.volume = 0 }
        player.play()
        player.setVolume(Self.volume, fadeDuration: 2)
    }

    /// Fades out, then pauses so the next puzzle picks up where the melody left off.
    func stop() {
        guard let player, player.isPlaying else { return }
        player.setVolume(0, fadeDuration: 1.5)
        fadeTask = Task {
            try? await Task.sleep(for: .seconds(1.5))
            guard !Task.isCancelled else { return }
            player.pause()
        }
    }
}
